import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { bulkOpenClaims, claimsKey } from './api';

/** A button that opens the selected claims together, and how many it opened and refused. The counts
 *  are cleared while it runs; the selection is cleared once it is done. */
export function BulkOpen({ sheetId, user, selected, onDone }: {
  sheetId: string; user: string; selected: number[]; onDone: () => void;
}) {
  const queryClient = useQueryClient();
  const runOnce = useSubmitOnce();
  const bulk = useMutation({
    mutationFn: (ids: number[]) => bulkOpenClaims(sheetId, user, ids),
    onSuccess: () => {
      onDone();
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  return (
    <div>
      <button type="button" data-testid="bulk-open" disabled={bulk.isPending}
        onClick={() => {
          const ids = [...selected];
          runOnce(() => {
            bulk.reset();
            return bulk.mutateAsync(ids);
          });
        }}>
        Open selected ({selected.length})
      </button>
      {bulk.isSuccess && (
        <>
          {' '}Opened <span data-testid="bulk-opened">{bulk.data.opened}</span>,{' '}
          refused <span data-testid="bulk-refused">{bulk.data.refused}</span>
        </>
      )}
      {bulk.isError && <span data-testid="bulk-open-error">The selected claims could not be opened.</span>}
    </div>
  );
}
        }
        return found;
    }

    /** The sheets of the sheet's tree: its root (the top of its parent chain, stopping at a sheet named
     *  twice) first, then the root's descendants, nearest first. */
    public java.util.List<String> tree(String id) {
        String root = id;
        java.util.Set<String> seen = new java.util.HashSet<>(java.util.List.of(id));
        for (String up = parent(root); up != null && seen.add(up); up = parent(up)) {
            root = up;
        }
        java.util.List<String> tree = new java.util.ArrayList<>(java.util.List.of(root));
        tree.addAll(descendants(root));
        if (!tree.contains(id)) tree.add(id);
        return tree;
    }

    private String parent(String id) {
        return jdbc.queryForList("SELECT val FROM sheet_setting WHERE sheet_id = ? AND setting = 'parent'",
                String.class, id).stream().filter((v) -> v != null && !v.isEmpty()).findFirst().orElse(null);
